from __future__ import annotations
import datetime as dt
from fastapi import HTTPException
from app.core.base import BaseService
from app.core.context import get_current_user_id
from app.core.serializer import serialize
from app.core.services import exposed_action
from ..models import Suggestion, Comment, Tag


class SuggestionService(BaseService):
    from ..models import Suggestion

    @exposed_action("write", groups=["feedback_moderation_group_moderator", "core_group_superadmin"])
    def publish(self, id: int, note: str | None = None, pin: bool = False) -> dict:
        rec = self.repo.session.get(Suggestion, int(id))
        if rec is None:
            raise HTTPException(404, "Suggestion not found")
        rec.status = "published"
        rec.is_public = True
        rec.published_at = dt.datetime.now(dt.timezone.utc)
        rec.reviewed_by_id = get_current_user_id()
        if note:
            rec.moderation_note = note
        self.repo.session.add(rec)
        self.repo.session.commit()
        self.repo.session.refresh(rec)
        return serialize(rec)

    @exposed_action("write", groups=["feedback_moderation_group_moderator", "core_group_superadmin"])
    def reject(self, id: int, note: str) -> dict:
        rec = self.repo.session.get(Suggestion, int(id))
        if rec is None:
            raise HTTPException(404, "Suggestion not found")
        rec.status = "rejected"
        rec.is_public = False
        rec.reviewed_by_id = get_current_user_id()
        rec.moderation_note = note
        self.repo.session.add(rec)
        self.repo.session.commit()
        self.repo.session.refresh(rec)
        return serialize(rec)

    @exposed_action("write", groups=["feedback_moderation_group_moderator", "core_group_superadmin"])
    def merge(self, id: int, target_id: int, note: str | None = None) -> dict:
        rec = self.repo.session.get(Suggestion, int(id))
        if rec is None:
            raise HTTPException(404, "Suggestion not found")
        target = self.repo.session.get(Suggestion, int(target_id))
        if target is None:
            raise HTTPException(404, "Target suggestion not found")
        rec.status = "merged"
        rec.is_public = False
        rec.reviewed_by_id = get_current_user_id()
        if note:
            rec.moderation_note = f"Merged into suggestion #{target_id}. {note}"
        self.repo.session.add(rec)
        self.repo.session.commit()
        self.repo.session.refresh(rec)
        return serialize(rec)

    @exposed_action("write", groups=["feedback_moderation_group_moderator", "core_group_superadmin"])
    def reopen(self, id: int) -> dict:
        rec = self.repo.session.get(Suggestion, int(id))
        if rec is None:
            raise HTTPException(404, "Suggestion not found")
        rec.status = "pending"
        rec.published_at = None
        rec.reviewed_by_id = None
        self.repo.session.add(rec)
        self.repo.session.commit()
        self.repo.session.refresh(rec)
        return serialize(rec)


